{
  "diagnosis": "F20.9",
  "candidates": ["F20.9", "F22", "F25.9"],
  "reason": "Patient presents with fixed persecutory delusions (belief that colleagues are deliberately tampering with his project data), markedly tangential/circumstantial speech with frequent derailment into unrelated tangents, and prominent negative symptoms (avolition, anhedonia, social withdrawal, blunted affect). Functional decline is clear and severe, spanning over two years (since taking over the contract), with significant occupational impairment (reassignment of work duties) and impaired self-care/home functioning requiring spousal prompting. No manic or depressive episode is present to suggest a mood disorder with psychotic features, and no substance use, medication changes, or medical/neurological conditions account for the presentation, ruling out substance-induced or secondary psychosis. The combination of active positive symptoms (delusions, disorganized speech) plus prominent negative symptoms, sustained over >6 months (actually >2 years) with clear functional decline, meets criteria for Schizophrenia, unspecified (F20.9). Differential diagnoses of Schizoaffective Disorder and Delusional Disorder were considered but are less fitting: no mood episode is present (against schizoaffective), and the presence of disorganized speech and negative symptoms extending beyond a single delusional theme argues against Delusional Disorder.",
  "diagnostic_checklist": {
    "symptom_groups": [
      {
        "group": "delusions",
        "confirmed_symptoms": [
          "Fixed belief that coworkers are intentionally planting errors in his data to sabotage his work",
          "Belief maintained despite reassurance from wife and junior analysts that it is only version-control error",
          "Delusion described as reaching full certainty about two months ago, though related suspicion/decline began over two years ago"
        ],
        "count": 3
      },
      {
        "group": "disorganized_speech",
        "confirmed_symptoms": [
          "Marked tangentiality and derailment during nearly every response",
          "Frequent unprompted digressions into unrelated topics (floppy disks, paint colors, cello, aquifers) before returning to the original question",
          "Loss of goal in conversation requiring redirection"
        ],
        "count": 3
      },
      {
        "group": "negative_symptoms",
        "confirmed_symptoms": [
          "Loss of motivation and interest in previously enjoyed activities (astronomy, hiking, mentoring)",
          "Social withdrawal, keeping to himself at home",
          "Avolition: sitting for hours without initiating activity",
          "Requires spousal prompting to maintain basic routines (eating, getting up)"
        ],
        "count": 4
      },
      {
        "group": "mood_symptoms_ruled_out",
        "confirmed_symptoms": [
          "Denies sustained depressed or elevated/irritable mood",
          "Describes mood as 'steady' and 'even-keeled'"
        ],
        "count": 2
      },
      {
        "group": "hallucinations_ruled_out",
        "confirmed_symptoms": [
          "Denies auditory or visual hallucinations",
          "Attributes auditory complaints to television sound mixing rather than perceptual disturbance"
        ],
        "count": 2
      }
    ],
    "duration_verified": "Functional decline and withdrawal began approximately 2 years and 2 months ago when he took over the modeling contract; delusional certainty crystallized about 2 months ago. Total symptom duration exceeds 6 months, meeting chronicity criteria for schizophrenia.",
    "functional_impairment": true,
    "traumatic_stressor": null,
    "psychosocial_stressor

